INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770599144668, 'Alpine OEM Fit', '테슬라 프론트 알파인 스피커 패키지 (무손상 OEM Fit)', '테슬라의 고요함 속, 알파인(ALPINE)의 프리미엄 사운드를 채우다', '전기차 특유의 조용한 실내, 이제 그 공간을 완벽한 감동으로 채울 시간입니다.', 1070000, 'https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/oem%20fit%20Tesla.jpg', '[{"id":"1773978677632102940","type":"text","value":"테슬라 모델 3, 모델 Y 오너 여러분!\n\n전기차 특유의 조용한 실내, 이제 그 공간을 완벽한 감동으로 채울 시간입니다.\n세계적인 카오디오 명가 **알파인(ALPINE)**이 오직 테슬라만을 위해 완성한 프리미엄 스피커 업그레이드 솔루션을 만나보세요."},{"id":"1773978706314543735","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/EV-65CF.jpg"},{"id":"1773978861473725382","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/EV-65CF-01.jpg"},{"id":"1773978905045775993","type":"text","value":"완벽한 타격감과 선명함, 프론트 도어 스피커 [EV-65CF]\n\n혁신적인 하이브리드 파이버 소재: 카본 파이버의 강력한 강성으로 뿜어내는 ''다이내믹한 저음''과, 방탄 파이버의 탄성이 빚어내는 ''달콤하고 투명한 보컬''을 동시에 구현합니다.\n\n맑은 고음의 완성: 티테론 돔 트위터 적용으로 답답했던 순정 사운드를 벗어나 왜곡 없이 맑고 청아한 고음을 선사합니다."},{"id":"1773978918471059219","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/EV-40MT.jpg"},{"id":"1773979010517364387","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/EV-40MT-01.jpg"},{"id":"1773979063925882480","type":"text","value":"눈앞에서 부르는 듯한 생생함, 대시보드 미드레인지 [EV-40MT]\n\n테슬라 실내 음향의 밸런스를 잡아주는 4인치 미드레인지 스피커입니다.\n\n운전석 정면에서 또렷하게 맺히는 보컬의 숨결과 풍성하고 입체적인 서라운드 스테이지를 경험해 보세요.\n\n\n\"매일 타는 테슬라, 이제 사운드도 혁신할 때입니다.\"\n\n단순한 음악 감상을 넘어 차 안을 나만의 프라이빗 콘서트홀로 만들어줄 알파인 EV-65CF & EV-40MT 시스템!\n지금 바로 예약하고 가슴 뛰는 하이엔드 오디오의 차이를 직접 경험해 보세요.\n\n\n바이지츠아우토\n경기도 하남시 대성로169번길 34\n010-9126-9223"}]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770599178435, 'Alpine OEM Fit', 'KGM 알파인오디오 옵션 차량 서브우퍼 패키지', '.', '', 600000, 'assets/images/KGM 서브우퍼 메인.jpg', '[{"id":"1770619100789.7793","type":"image","value":"assets/images/KGM서브우퍼패키지.jpg"},{"id":"1770619112639.6072","type":"text","value":"서울/송파 오토갤러리 010-5220-8034 서울시 송파구 새말로 176 트윈팰리스 101동 102호\n\n인천/서구 썬카펙토리 010-9773-9882 인천 서구 봉수대로 166 2동 101호\n\n인천/미추홀구 에이스카오디오 010-2562-9956 인천 미추홀구 한나루 540-1\n\n강원/속초 레트로카오디오 010-6879-9255 강원 속초시 청호로 40\n\n경기/분당 개구리카오디오 010-5283-6277 경기 성남시 분당구 대왕판교로 255\n\n경기/성남 카투오디오 010-3597-1735 경기 성남시 중원구 둔촌대로64번길 4-16(101호)\n\n경기/광명 사운드테크닉 010-4764-7777 경기 광명시 금오로 745\n\n경기/양주 럭셔리카클럽 010-9956-3618 경기 양주시 부흥로 1324\n\n경기/화성 카오디오팩토리 010-6580-1975 경기 화성시 동탄반송2길 41-7\n\n전북/전주 퍼니사운드 010-5123-9255 전북 전주시 덕진구 쪽구름2길 34 1층 101\n\n광주/남구 광주카오디오 010-3627-9072 광주 남구 독립로 163\n\n제주/제주시 사운드째즈 010-3693-9499 제주 제주시 연삼로 124\n\n​\n\n[알파인 대리점]\n\n서울/서초 바이지츠아우토 010-3656-6276 서울 서초구 명달로 52-7 미양빌딩\n\n서울/강남 카사운드메이커 010-2618-2455 서울특별시 서초구 강남대로 101안길 36\n\n경기/구리 현대카오디오 010-3795-4826 경기도 구리시 수택동 430\n\n경기/하남 바이지츠아우토 010-9092-2692 경기 하남시 대성로169번길 34\n\n충남/아산 퀄리티 하우스 010-4816-9221 충남 아산시 삼동로 70\n\n대전/서구 파워뱅크하우스 010-5407-4999 대전 서구 도산로 465\n\n대구/남구 핸즈카오디오 010-9077-6658 대구 남구 효성로 15 미리내맨션 상가\n\n전북/익산 카사운드메이커 010-2618-2455 전북 익산시 익산대로 68\n\n강원/속초 레트로카오디오 010-6879-9255 강원특별자치도 속초시 청호로 40\n\n부산/강서 사운드닥터 010-4855-8949 부산 강서구 대저중앙로 139"}]'::jsonb, '[]'::jsonb, 'https://kgm-m770-pc-v2-v2.vercel.app/') ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770599246780, 'Alpine OEM Fit', 'BMW 스피커 패키지 (무손상 OEM Fit)', '진정한 드라이빙의 완성! BMW 오너를 위한 알파인(ALPINE) 프리미엄 스피커 업그레이드', 'BMW 전용 알파인 스피커 세트', 2160000, 'https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/OEM%20fit%20BMW.jpg', '[{"id":"1773980204930262326","type":"text","value":"BMW의 다이내믹한 퍼포먼스에 걸맞은 완벽한 사운드를 찾고 계신가요?\n순정 오디오의 아쉬움을 단번에 채워줄 세계적인 카오디오 명가 **알파인(ALPINE)**의 BMW 전용 스피커 솔루션을 소개합니다!\n\n이번에 제안 드리는 세팅은 프론트와 리어를 책임질 DP2-45-B와 사운드의 중심을 잡아줄 센터 스피커 DP2-40C-B의 환상적인 조합으로, 차 안을 나만의 프라이빗 콘서트홀로 만들어줍니다."},{"id":"1773980306884349584","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/DP245Cb.jpg"},{"id":"1773980339379814767","type":"text","value":"프론트 & 리어의 압도적인 타격감 [DP2-45-B]\n\n4.5인치 2-Way 코엑셜 스피커: 전면과 후면을 꽉 채우는 풍성하고 입체적인 사운드를 제공합니다.\n\n혁신적인 하이브리드 파이버 소재: 카본 파이버와 방탄 파이버(Bulletproof Fiber)를 결합한 콘이 단단하고 다이내믹한 베이스를 뿜어냅니다.\n\nH.A.M.R 서라운드 기술 적용: 높은 볼륨에서도 베이스의 일그러짐 없이 파워풀하고 정교한 소리를 전달합니다."},{"id":"1773980353054902530","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/DP240Cb.jpg"},{"id":"1773980370485801625","type":"text","value":"선명한 보컬과 완벽한 밸런스, 센터 스피커 [DP2-40C-B]\n\n4인치 2-Way 컴포넌트 스피커: 실내 사운드의 중심을 단단하게 잡아주어, 대시보드 위에 진짜 무대가 펼쳐진 듯한 탁월한 공간감을 선사합니다.\n\n테트론(Tetoron) 소프트 돔 트위터: 답답했던 순정의 고음을 벗어나 왜곡 없이 맑고 청아한 해상력으로 보컬의 숨결까지 생생하게 재생합니다.\n\n\"BMW의 품격, 이제 사운드로 증명할 때입니다.\"\n\n매일 엑셀을 밟는 순간이 감동으로 채워집니다. 믿고 듣는 알파인(ALPINE)의 디지털 프리시전(DP) 시리즈로 하이엔드 오디오의 확연한 차이를 직접 경험해 보세요!\n\n장착 대리점 안내\n\n아래 링크를 클릭 하시면 전국의 알파인 대리점을 확인 할 수 있습니다.\n\n전화로 문의 해보세요\nhttps://www.alpine-korea.co.kr/pages/dealers.html\n"},{"id":"1774013031382914448","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/OEM%20Fit%20BMW-02.jpg"}]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
